/**
 * SLATE — work in the countries outside the thirteen.
 *
 * Generated by `probe/gen-work-world.cjs` from research on 2026-09-25
 * (`probe/job-research/world-*.jsonl`, brief in `WORLD-BRIEF.md`): each
 * country's minimum wage (read by `content/wages.ts`), its usual payday
 * (`content/jobs.ts`), a simplified payroll of the employee's own
 * contributions and the income tax on wages (`content/payroll.ts`), and
 * its statutory annual leave (`content/labor.ts`). Its employers are in
 * `content/employers.ts`. Every figure carries its source; what the
 * research couldn't find isn't here, and SLATE's estimate stands in for it
 * and says so. Money in hundredths where it's a wage, whole units where
 * it's a band or an allowance, in the country's own currency.
 */

export interface WorldWork {
  minimum?: { hourly: number; currency: string; kind: 'statutory' | 'agreement'; from?: string; source: string; note?: string };
  pay?: { cycle: 'monthly' | 'semimonthly' | 'biweekly' | 'weekly'; day?: number | 'last'; source: string };
  payroll?: {
    /** A contribution at one rate, or on a progressive scale of [from, rate] bands (Brazil's INSS). */
    employee: readonly { name: string; rate: number; bands?: readonly (readonly [number, number])[]; capYearly?: number; pension?: boolean }[];
    employerPension?: { name: string; rate: number };
    tax?: { brackets: readonly (readonly [number, number])[]; allowance?: number; credit?: number; source: string };
    source: string;
  };
  leaveDays?: { days: number; source: string };
}

